        [209845] = "Hechizos para la manipulaci\195\179n y el enga\195\177o. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [209846] = "Observaciones y apuntes sobre el Sue\195\177o Esmeralda. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [209847] = "Consejos (muy mal organizados) para la resoluci\195\179n de problemas relativos a la tecnolog\195\173a goblin. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [209848] = "Est\195\161n escritos en un escritura tit\195\161nica perdida, pero siguen siendo una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [209849] = "Escrito por el doctor Krastinov. Una incorporaci\195\179n cuestionable a la biblioteca de cualquier coleccionista.",
        [209850] = "Una reliquia de los grandes imperios ogros de Draenor. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [209851] = "Los secretos chaman\195\173sticos mejor guardados del clan T\195\179tem Siniestro. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [210177] = "Escritos de un importante archimago del Kirin Tor. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [213165] = "Bosquejo de investigaci\195\179n sobre el uso de las partes de un basilisco como componentes. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [215683] = "Teor\195\173as sobre el origen y el uso de la magia elemental. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [215815] = "Una gu\195\173a introductoria a la magia defensiva y las barreras. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [215816] = "Una tesis incompleta que afirma que las ara\195\177as son inofensivas. Aun as\195\173, sigue siendo una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [215817] = "Un extra\195\177o texto en defensa de los demonios. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [215820] = "Una serie de relatos lo suficientemente aterradores como para asustar al m\195\161s bravo de los guerreros. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [215822] = "Los extra\195\177os pasajes de esta obra a\195\186n se pueden leer a pesar de estar medio borrosos por la acci\195\179n del agua. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [215824] = "Repleto de consejos \195\186tiles para mantener a los diablillos alejados de tus componentes. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [220345] = "Contiene una descripci\195\179n general de poderosos rituales de sangre. Una incorporaci\195\179n controvertida a la biblioteca de cualquier coleccionista.",
        [220346] = "Un volumen cubierto de notas ilegibles y diagramas garabateados por una mano inestable. A\195\186n podr\195\173a ser una incorporaci\195\179n decente a la biblioteca de cualquier coleccionista.",
        [220347] = "Las palabras flotan en la p\195\161gina, lo que supone un desaf\195\173o para su lectura. Una incorporaci\195\179n confusa a la biblioteca de cualquier coleccionista.",
        [220348] = "Una gu\195\173a sobre la funci\195\179n de la magia b\195\161sica en la alta sociedad de los Altonatos. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [220349] = "Un compendio de buenas t\195\169cnicas arquitect\195\179nicas, capaces de soportar todos los desastres salvo los catacl\195\173smicos. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [220350] = "Notas sobre las propiedades de manipulaci\195\179n mental de varios venenos y toxinas. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [220352] = "T\195\169cnicas de los enanos para aplicar magia a la metalurgia, la explotaci\195\179n minera y la industria pesada. Una incorporaci\195\179n educativa aunque l\195\186gubre a la biblioteca de cualquier coleccionista.",
        [220353] = "Una colecci\195\179n de hechizos y teor\195\173as arcanas anteriores a la guerra que, en gran parte, han ca\195\173do en desuso. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [228132] = "Notas sobre el impacto de la Plaga en la agricultura. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [228133] = "Notas bien documentadas sobre las diferencias entre los distintos elementales de fuego. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [228134] = "La gu\195\173a definitiva para recorrer el norte de Kalimdor. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [228135] = "Ense\195\177anzas de la Luz con anotaciones desde la perspectiva de un mago famoso. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [228136] = "Escritos inconexos en los que un ingeniero emprendedor explica c\195\179mo integrar explosivos en la tecnolog\195\173a. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [228138] = "Una novela de ficci\195\179n muy antigua con anotaciones manuscritas en los m\195\161rgenes. Una incorporaci\195\179n interesante a la biblioteca de cualquier coleccionista.",
        [228140] = "Una recolecci\195\179n de notas pol\195\169micas que cuestionan los peligros de la Plaga. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
        [228141] = "Una gu\195\173a para principiantes sobre los primeros pasos en la resurrecci\195\179n de muertos. Una incorporaci\195\179n estupenda a la biblioteca de cualquier coleccionista.",
    },
}
all.esMX = {
    strings = {
        ["Apothecary Society Primer"] = "Manual de Sociedad de Boticarios",
        ["Book"] = "Libro",
        ["Dalaran Digest"] = "Compendio de Dalaran",
        ["Gnomish Tome"] = "Tomo gn\195\179mico",
        ["Goblin Tome"] = "Tomo goblin",
        ["Horde characters can take it too. A Horde reader looted it here, and the librarian in Undercity offered its quest. They told us on September 30, 2026."] = "Los personajes de la Horda tambi\195\169n pueden cogerlo. Un lector de la Horda lo despoj\195\179 aqu\195\173 y el bibliotecario de Entra\195\177as le ofreci\195\179 su misi\195\179n. Nos lo cont\195\179 el 30 de septiembre de 2026.",
        ["In a burned house by the lake (zockify.com, wowsod.pro). Players reach it on a death run."] = "En una casa quemada junto al lago (zockify.com, wowsod.pro). Los jugadores llegan con una carrera de fantasma.",
        ["In a small house by the lake. A reader picked it up there on October 2, 2026."] = "En una casita junto al lago. Un lector lo cogi\195\179 all\195\173 el 2 de octubre de 2026.",
        ["In the cave of Timbermaw Hold, the tunnel between Felwood and Winterspring. A player found it there on September 24, 2026."] = "En la cueva del Basti\195\179n de los Fauces de Madera, el t\195\186nel entre Frondavil y Cuna del Invierno. Un jugador lo encontr\195\179 all\195\173 el 24 de septiembre de 2026.",
        ["Inside Blackrock Mountain on a platform before the Blackrock Depths entrance, not in the instance: 48.4, 63.6 on the Blackrock Mountain map. The pin marks the mountain, not the book."] = "Dentro de la Monta\195\177a Roca Negra, sobre una plataforma antes de la entrada a las Profundidades de Roca Negra, fuera de la instancia: 48.4, 63.6 en el mapa de la Monta\195\177a Roca Negra. El marcador se\195\177ala la monta\195\177a, no el libro.",
        ["Inside the catacomb there, in the last room, on a wooden table at the far end. A reader found it there on September 29, 2026."] = "Dentro de la catacumba, en la \195\186ltima sala, sobre una mesa de madera al fondo. Un lector lo encontr\195\179 all\195\173 el 29 de septiembre de 2026.",
        ["Inside the chapel building of Light's Hope Chapel, the Argent Dawn's camp. Three players reported it there on September 24, 2026, one of them with coordinates."] = "Dentro del edificio de la capilla de la Capilla de la Esperanza de la Luz, el campamento del Alba Argenta. Tres jugadores lo vieron all\195\173 el 24 de septiembre de 2026, uno de ellos con coordenadas.",
        ["Library Book"] = "Libro de biblioteca",
        ["Location and Scrolls container confirmed by two players on September 22, 2026. Enter the cave at Lushwater Oasis (The Barrens, 46.0, 36.5), then head to the Cavern of Mists, near the Wailing Caverns instance entrance. Look for Scrolls at 52.8, 54.7 on the cave map."] = "Ubicaci\195\179n y contenedor (Pergaminos) confirmados por dos jugadores el 22 de septiembre de 2026. Entra en la cueva del Oasis Aguaverde (Los Bald\195\173os, 46.0, 36.5) y ve a la caverna de las brumas, junto a la entrada de la instancia de las Cuevas de los Lamentos. Busca los Pergaminos en 52.8, 54.7 del mapa de la cueva.",
        ["Location confirmed by a player on September 22, 2026."] = "Ubicaci\195\179n confirmada por un jugador el 22 de septiembre de 2026.",
        ["Manual"] = "Manual",
        ["Mysterious Book"] = "Libro misterioso",
        ["Not confirmed in Forever: the Season of Discovery spot, still in Wowhead's Forever data."] = "Sin confirmar en Forever: es el sitio de Season of Discovery, que sigue en los datos de Forever de Wowhead.",
        ["On a shelf behind the alchemy supplier in Everlook. A player confirmed it there on September 24, 2026."] = "En una estanter\195\173a detr\195\161s del proveedor de alquimia de Vista Eterna. Un jugador lo confirm\195\179 all\195\173 el 24 de septiembre de 2026.",
        ["On a table in the ruined keep of Caer Darrow, at the top of the Scholomance building, outside the dungeon. Two players found it there on September 23 and 24, 2026."] = "Sobre una mesa en la torre en ruinas de Castel Darrow, en lo alto del edificio de Scholomance, fuera de la mazmorra. Dos jugadores lo encontraron all\195\173 el 23 y el 24 de septiembre de 2026.",
        ["On a table to the right before crossing the bridge to Stratholme, outside the instance (zockify.com, wowsod.pro). Two undead stand close by."] = "Sobre una mesa a la derecha antes de cruzar el puente hacia Stratholme, fuera de la instancia (zockify.com, wowsod.pro). Hay dos no-muertos muy cerca.",
        ["On a wooden platform to the right of the mine's mouth, so you never go into the mine itself."] = "En una plataforma de madera a la derecha de la boca de la mina, as\195\173 que no hace falta entrar en la mina.",
        ["On the altar of the tomb in the middle of Blackrock Mountain, where a dwarf's ghost stands. You reach it without entering a dungeon. Another report places it inside Blackrock Mountain, Center Vault, on the large platform (about 48.6, 64.2 on the Blackrock Mountain map)."] = "En el altar de la tumba del centro de la Monta\195\177a Roca Negra, donde est\195\161 el fantasma de un enano. Se llega sin entrar en ninguna mazmorra. Otro informe lo sit\195\186a dentro de la Monta\195\177a Roca Negra, en la c\195\161mara central, sobre la gran plataforma (hacia 48.6, 64.2 en el mapa de la Monta\195\177a Roca Negra).",
        ["On the ground at the eastern edge of the murloc camp: you can walk to it and walk back out."] = "En el suelo, en el borde este del campamento m\195\186rloc: puedes llegar andando y volver a salir.",
        ["On top of the Sunken Temple, outside the dungeon."] = "En lo alto del Templo Sumergido, fuera de la mazmorra.",
        ["Players report that the book sits inside a cage that opens with the Rusted Cage Key. A reader found the key listed on Wowhead as a rare drop, about 1%, of the Muckdweller murlocs around the cage. Looting it through the bars no longer works in Forever (Wowhead comment, 2026-09-30)."] = "Los jugadores cuentan que el libro est\195\161 dentro de una jaula que se abre con una llave de jaula oxidada. Un lector encontr\195\179 la llave en Wowhead como bot\195\173n raro (alrededor del 1 %) de los m\195\186rlocs de alrededor de la jaula. Despojarlo a trav\195\169s de los barrotes ya no funciona en Forever (comentario en Wowhead, 30-09-2026).",
        ["Research Notes"] = "Notas de investigaci\195\179n",
        ["Scrolls"] = "Pergaminos",
        ["Spellbook"] = "Libro de hechizos",
        ["Stratholme bridge"] = "puente de Stratholme",
        ["Ta'zo Mural"] = "Mural de Ta'zo",
        ["The first tower you meet entering the ogre fortress, from Tarren Mill or from Strahnbrad. The manual is inside it."] = "La primera torre que encuentras al entrar en la fortaleza de los ogros, desde Molino Tarren o desde Strahnbrad. El manual est\195\161 dentro.",
        ["The lowest zone of the eight, and the path up the pinnacle starts at 31.0, 37.0. The scrolls are in the largest hut."] = "La zona de menor nivel de las ocho; el camino que sube a la cumbre empieza en 31.0, 37.0. Los pergaminos est\195\161n en la caba\195\177a m\195\161s grande.",
        ["Waterlogged Book"] = "Libro anegado",
        ["Wowhead's Forever database puts it here (read on October 1, 2026). No player has confirmed it to us yet."] = "La base de datos de Forever de Wowhead lo sit\195\186a aqu\195\173 (consultada el 1 de octubre de 2026). Ning\195\186n jugador nos lo ha confirmado todav\195\173a.",
        ["cave entrance"] = "entrada de la cueva",
    },
