        ["On a shelf behind the alchemy supplier in Everlook. A player confirmed it there on September 24, 2026."] = "\235\136\136\235\167\157\235\163\168 \235\167\136\236\157\132\236\157\152 \236\151\176\234\184\136\236\136\160 \236\131\129\236\157\184 \235\146\164\237\142\184 \236\132\160\235\176\152 \236\156\132\236\151\144 \236\158\136\236\138\181\235\139\136\235\139\164. 2026\235\133\132 9\236\155\148 24\236\157\188\236\151\144 \237\149\156 \237\148\140\235\160\136\236\157\180\236\150\180\234\176\128 \234\183\184\234\179\179\236\151\144\236\132\156 \237\153\149\236\157\184\237\150\136\236\138\181\235\139\136\235\139\164.",
        ["On a table in the ruined keep of Caer Darrow, at the top of the Scholomance building, outside the dungeon. Two players found it there on September 23 and 24, 2026."] = "\235\141\152\236\160\132 \235\176\150, \236\138\164\236\185\188\235\161\156\235\167\168\236\138\164 \234\177\180\235\172\188 \234\188\173\235\140\128\234\184\176\236\151\144 \236\158\136\235\138\148 \236\185\180\236\151\152 \235\139\164\235\161\156\236\154\176\236\157\152 \237\143\144\237\151\136\234\176\128 \235\144\156 \236\132\177\236\177\132 \236\149\136 \237\131\129\236\158\144 \236\156\132\236\151\144 \236\158\136\236\138\181\235\139\136\235\139\164. 2026\235\133\132 9\236\155\148 23\236\157\188\234\179\188 24\236\157\188\236\151\144 \237\148\140\235\160\136\236\157\180\236\150\180 \235\145\144 \235\170\133\236\157\180 \234\183\184\234\179\179\236\151\144\236\132\156 \236\176\190\236\149\152\236\138\181\235\139\136\235\139\164.",
        ["On a table to the right before crossing the bridge to Stratholme, outside the instance (zockify.com, wowsod.pro). Two undead stand close by."] = "\236\157\184\236\138\164\237\132\180\236\138\164 \235\176\150, \236\138\164\237\138\184\235\157\188\236\134\148\235\166\132\236\156\188\235\161\156 \234\176\128\235\138\148 \235\139\164\235\166\172\235\165\188 \234\177\180\235\132\136\234\184\176 \236\160\132 \236\152\164\235\165\184\236\170\189\236\157\152 \237\131\129\236\158\144 \236\156\132(zockify.com, wowsod.pro). \235\176\148\235\161\156 \236\152\134\236\151\144 \236\150\184\235\141\176\235\147\156 \235\145\152\236\157\180 \236\132\156 \236\158\136\236\138\181\235\139\136\235\139\164.",
        ["On a wooden platform to the right of the mine's mouth, so you never go into the mine itself."] = "\234\180\145\236\130\176 \236\158\133\234\181\172 \236\152\164\235\165\184\236\170\189\236\157\152 \235\130\152\235\172\180 \235\176\156\237\140\144 \236\156\132\236\151\144 \236\158\136\236\150\180\236\132\156 \234\180\145\236\130\176 \236\149\136\236\156\188\235\161\156 \235\147\164\236\150\180\234\176\136 \237\149\132\236\154\148\234\176\128 \236\151\134\236\138\181\235\139\136\235\139\164.",
        ["On the altar of the tomb in the middle of Blackrock Mountain, where a dwarf's ghost stands. You reach it without entering a dungeon. Another report places it inside Blackrock Mountain, Center Vault, on the large platform (about 48.6, 64.2 on the Blackrock Mountain map)."] = "\234\178\128\236\157\128\235\176\148\236\156\132 \236\130\176 \237\149\156\234\176\128\236\154\180\235\141\176, \235\147\156\236\155\140\237\148\132 \236\156\160\235\160\185\236\157\180 \236\132\156 \236\158\136\235\138\148 \235\172\180\235\141\164\236\157\152 \236\160\156\235\139\168 \236\156\132\236\151\144 \236\158\136\236\138\181\235\139\136\235\139\164. \235\141\152\236\160\132\236\151\144 \235\147\164\236\150\180\234\176\128\236\167\128 \236\149\138\234\179\160\235\143\132 \234\176\136 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164. \235\139\164\235\165\184 \236\160\156\235\179\180\236\151\144 \235\148\176\235\165\180\235\169\180 \234\178\128\236\157\128\235\176\148\236\156\132 \236\130\176 \235\130\180\235\182\128 \236\164\145\236\149\153 \236\132\157\236\139\164\236\157\152 \237\129\176 \235\176\156\237\140\144 \236\156\132\236\151\144 \236\158\136\236\138\181\235\139\136\235\139\164(\234\178\128\236\157\128\235\176\148\236\156\132 \236\130\176 \236\167\128\235\143\132\236\157\152 \236\149\189 48.6, 64.2).",
        ["On the ground at the eastern edge of the murloc camp: you can walk to it and walk back out."] = "\235\169\128\235\161\157 \236\149\188\236\152\129\236\167\128 \235\143\153\236\170\189 \235\129\157\236\157\152 \235\149\133 \236\156\132\236\151\144 \236\158\136\236\138\181\235\139\136\235\139\164. \234\177\184\236\150\180\236\132\156 \235\139\164\235\133\128\236\152\172 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164.",
        ["On top of the Sunken Temple, outside the dungeon."] = "\235\141\152\236\160\132 \235\176\150, \234\176\128\235\157\188\236\149\137\236\157\128 \236\130\172\236\155\144 \234\188\173\235\140\128\234\184\176\236\151\144 \236\158\136\236\138\181\235\139\136\235\139\164.",
        ["Players report that the book sits inside a cage that opens with the Rusted Cage Key. A reader found the key listed on Wowhead as a rare drop, about 1%, of the Muckdweller murlocs around the cage. Looting it through the bars no longer works in Forever (Wowhead comment, 2026-09-30)."] = "\237\148\140\235\160\136\236\157\180\236\150\180\235\147\164\236\151\144 \235\148\176\235\165\180\235\169\180 \236\177\133\236\157\128 \235\133\185\236\138\168 \236\154\176\235\166\172 \236\151\180\236\135\160\235\161\156 \236\151\172\235\138\148 \236\154\176\235\166\172 \236\149\136\236\151\144 \236\158\136\236\138\181\235\139\136\235\139\164. \237\149\156 \235\143\133\236\158\144\234\176\128 Wowhead\236\151\144\236\132\156 \236\157\180 \236\151\180\236\135\160\234\176\128 \236\154\176\235\166\172 \236\163\188\235\179\128\236\157\152 Muckdweller \235\169\128\235\161\157\236\151\144\234\178\140\236\132\156 \235\147\156\235\172\188\234\178\140(\236\149\189 1%) \235\150\168\236\150\180\236\167\132\235\139\164\235\138\148 \236\160\149\235\179\180\235\165\188 \236\176\190\236\149\152\236\138\181\235\139\136\235\139\164. Forever\236\151\144\236\132\156\235\138\148 \235\141\148 \236\157\180\236\131\129 \236\176\189\236\130\180 \235\132\136\235\168\184\235\161\156 \237\154\141\235\147\157\237\149\160 \236\136\152 \236\151\134\236\138\181\235\139\136\235\139\164(Wowhead \235\140\147\234\184\128, 2026-09-30).",
