        ["The lowest zone of the eight, and the path up the pinnacle starts at 31.0, 37.0. The scrolls are in the largest hut."] = "\236\151\172\235\141\159 \234\179\179 \236\164\145 \235\160\136\235\178\168\236\157\180 \234\176\128\236\158\165 \235\130\174\236\157\128 \236\167\128\236\151\173\236\157\180\235\169\176, \235\180\137\236\154\176\235\166\172\235\161\156 \236\152\172\235\157\188\234\176\128\235\138\148 \234\184\184\236\157\128 31.0, 37.0\236\151\144\236\132\156 \236\139\156\236\158\145\237\149\169\235\139\136\235\139\164. \235\145\144\235\163\168\235\167\136\235\166\172\235\138\148 \234\176\128\236\158\165 \237\129\176 \236\152\164\235\145\144\235\167\137 \236\149\136\236\151\144 \236\158\136\236\138\181\235\139\136\235\139\164.",
