        [213165] = "Uma tentativa de pesquisa sobre o uso de \195\179rg\195\163os de basiliscos como reagentes. Uma bela adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [215683] = "Teorias sobre a origem e o uso de magia elemental. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [215815] = "Um guia introdut\195\179rio \195\160s magias e barreiras defensivas. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [215816] = "Uma tese incompleta que defende que as aranhas s\195\163o inofensivas, mas ainda assim uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [215817] = "Um pouco autoindulgente, mas ainda assim, uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [215820] = "Contos que assustariam at\195\169 os mais ferrenhos guerreiros. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [215822] = "O estranho texto est\195\161 apagado, mas relativamente leg\195\173vel, mesmo com os danos da \195\161gua. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [215824] = "Cont\195\169m dicas \195\186teis sobre como cuidar de mascotes diabretes com seus reagentes. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [220345] = "Descreve diversos rituais de sangue poderosos. Uma adi\195\167\195\163o controversa \195\160 cole\195\167\195\163o de qualquer biblioteca.",
