        [220347] = "As palavras nadam na p\195\161gina, desafiando tentativas de l\195\170-las. Uma adi\195\167\195\163o intrigante \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [220348] = "Um guia sobre o papel da magia elementar na polida sociedade Altaneira. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [220349] = "T\195\169cnicas arquitet\195\180nicas robustas, capazes de resistir a todos os desastres, exceto os mais catacl\195\173smicos. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [220350] = "Anota\195\167\195\181es sobre as propriedades de altera\195\167\195\163o mental de v\195\161rias toxinas e venenos. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [220352] = "T\195\169cnicas en\195\162nicas para aplicar magia \195\160 metalurgia, minera\195\167\195\163o e ind\195\186stria pesada. Uma adi\195\167\195\163o informativa, ainda que sem gra\195\167a, \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [220353] = "Uma cole\195\167\195\163o de feiti\195\167os e teorias arcanas anterior \195\160 guerra que, em grande parte, j\195\161 caiu em desuso. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [228132] = "Anota\195\167\195\181es sobre o impacto do flagelo na agropecu\195\161ria. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [228133] = "Anota\195\167\195\181es informativas categorizando elementais de fogo. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [228134] = "O guia de viagens definitivo para o extremo norte de Kalimdor. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [228135] = "Ensinamentos da Luz com anota\195\167\195\181es da perspectiva de um mago famoso. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [228136] = "Anota\195\167\195\181es de um engenheiro empreendedor sobre a integra\195\167\195\163o de explosivos na tecnologia. Uma boa adi\195\167\195\163o \195\160 cole\195\167\195\163o de qualquer biblioteca.",
        [228138] = "Um romance surrado com anota\195\167\195\181es \195\160 m\195\163o nas margens. Uma adi\195\167\195\163o interessante \195\160 cole\195\167\195\163o de qualquer biblioteca.",
