        ["On a table to the right before crossing the bridge to Stratholme, outside the instance (zockify.com, wowsod.pro). Two undead stand close by."] = "\208\157\208\176 \209\129\209\130\208\190\208\187\208\181 \209\129\208\191\209\128\208\176\208\178\208\176 \208\191\208\181\209\128\208\181\208\180 \208\188\208\190\209\129\209\130\208\190\208\188 \208\178 \208\161\209\130\209\128\208\176\209\130\209\133\208\190\208\187\209\140\208\188, \208\178\208\189\208\181 \208\191\208\190\208\180\208\183\208\181\208\188\208\181\208\187\209\140\209\143 (zockify.com, wowsod.pro). \208\160\209\143\208\180\208\190\208\188 \209\129\209\130\208\190\209\143\209\130 \208\180\208\178\208\190\208\181 \208\189\208\181\208\182\208\184\209\130\208\184.",
