        ["On the ground at the eastern edge of the murloc camp: you can walk to it and walk back out."] = "\208\157\208\176 \208\183\208\181\208\188\208\187\208\181 \209\131 \208\178\208\190\209\129\209\130\208\190\209\135\208\189\208\190\208\179\208\190 \208\186\209\128\208\176\209\143 \208\187\208\176\208\179\208\181\209\128\209\143 \208\188\209\131\209\128\208\187\208\190\208\186\208\190\208\178: \208\188\208\190\208\182\208\189\208\190 \208\180\208\190\208\185\209\130\208\184 \208\180\208\190 \208\189\208\181\208\181 \208\184 \209\129\208\191\208\190\208\186\208\190\208\185\208\189\208\190 \209\131\208\185\209\130\208\184.",
